def _builtin(spec, snapshots, config, statistics, device, base, *, ancestor_artifact_hashes=None):
    kind = spec["kind"]
    payloads = [snapshots[_path(p, base)] for p in spec["model_paths"]]
    if kind in NEURAL_KINDS:
