            if (
                not isinstance(downstream, dict)
                or downstream.get("mode") != spec["mode"]
                or any(
                    downstream.get(k) != config.get(k)
                    for k in ("method", "seed", "history", "batch_size")
                )
            ):
                raise ValueError("Exact saved downstream config/identity required.")
