                len(x), 3, 5
            )
            return np.sort(prediction, axis=-1)

        return forecast

    def forecast(x, observed, metadata, query):
        # Exact native_references.run indexing; no standalone immutable helper exists.
        values = (
            np.repeat(x[:, -1, 0, None], 3, axis=1)
            if kind == "persistence"
