                "quantile_range_db_per_horizon": np.ptp(predictions, axis=0).tolist(),
                "diagnostic_only": True,
            },
            "status": "ASSESSABLE"
            if metrics["primary_pinball_db"] is not None
            else "NOT_ASSESSABLE",
