def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    for flag in (
        "train",
        "dev",
        "train-cohort",
        "dev-cohort",
        "split",
        "adr0016",
        "protocol",
        "config",
        "review",
        "output",
